#!/usr/bin/env bash
# The integration package as a DELTA against CURRENT (dirty) main, for root: one unified diff of every candidate file
# that differs from main's copy, plus a hash inventory of both sides. Main is only READ. (cwd work/app-lease-gas)
#   bash scripts/delta-against-main.sh   -> patches/current-main-delta.patch, patches/current-main-inventory.txt
#   DELTA_NAME=record bash scripts/delta-against-main.sh -> patches/record-main-{delta.patch,inventory.txt,inventory.status}
set -u
cd "$(dirname "$0")/.."
M=../enclave
N=${DELTA_NAME:-current}
# candidate file : main path
PAIRS=(
  "client/lease-executor-client.mjs:client/lease-executor-client.mjs"
  "client/lease-executor-authority.mjs:client/lease-executor-authority.mjs"
  "network/lease-gas-owner.mjs:network/lease-gas-owner.mjs"
  "network/lease-gas-runtime.mjs:network/lease-gas-runtime.mjs"
  "network/lease-release-journal.mjs:network/lease-release-journal.mjs"
  "network/lease-relay-service.mjs:network/lease-relay-service.mjs"
  "network/lease-executor-authority.mjs:network/lease-executor-authority.mjs"
  "cli/lease-gas.mjs:cli/lease-gas.mjs"
  "contracts/EnclaveLeaseExecutor.sol:contracts/EnclaveLeaseExecutor.sol"
  "contracts/EnclaveLeaseGasReserve.sol:contracts/EnclaveLeaseGasReserve.sol"
  "shadow-win/windows/node/chain.mjs:windows/node/chain.mjs"
  "shadow-win/windows/node/host.mjs:windows/node/host.mjs"
  "shadow-b/supervisor.js:supervisor.js"
  "shadow-b/Dockerfile:Dockerfile"
)
# main-layout files staged in port-main/ (ported tests, the record generator, the relay packaging): main path = path there
for f in $(cd port-main && find . -type f | sed 's#^\./##' | sort); do PAIRS+=("port-main/$f:$f"); done
: > patches/$N-main-delta.patch; : > patches/$N-main-inventory.status
{
  echo "# candidate vs CURRENT main ($(date -u +%FT%TZ)); sha256 candidate / main / status"
  for p in "${PAIRS[@]}"; do
    c=${p%%:*}; m=${p#*:}
    hc=$(sha256sum "$c" | cut -c1-64); hm=$( [ -f "$M/$m" ] && sha256sum "$M/$m" | cut -c1-64 || echo "absent")
    if [ "$hc" = "$hm" ]; then st="same as main"
    elif [ "$hm" = absent ]; then st="NEW"; diff -u --label /dev/null --label "b/$m" /dev/null "$c" >> patches/$N-main-delta.patch
    else st="CHANGED"; diff -u --label "a/$m" --label "b/$m" "$M/$m" "$c" >> patches/$N-main-delta.patch; fi
    echo "$hc  $hm  $m  ($c) $st"
    echo "$hc $hm $( [ "$st" = "same as main" ] && echo same || echo "$m" ) $c $st" >> patches/$N-main-inventory.status
  done
  b=overlay-main/windows/node/lease-gas-runtime.bundle.mjs; m=windows/node/lease-gas-runtime.bundle.mjs   # main's builder, run in overlay-main
  echo "$(sha256sum $b | cut -c1-64)  $(sha256sum $M/$m | cut -c1-64)  $m  (generated by main's scripts/build-windows-lease-runtime.mjs over the candidate sources in overlay-main; not diffed, regenerate it)"
} > patches/$N-main-inventory.txt
cat patches/$N-main-inventory.txt
